using System.Collections.Frozen;
using System.Runtime.InteropServices;

namespace CatalogSvc;

/// <summary>
/// Product catalog optimized for read-heavy lookup workloads.
/// Uses FrozenDictionary for faster lookups and a reverse index
/// to eliminate full-scan filtering by category.
/// Call <see cref="Build"/> after adding products to freeze the catalog.
/// </summary>
public class ProductCatalog
{
    private readonly Dictionary<string, string> _categories = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, decimal> _prices = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, List<string>> _categoryIndex = new(StringComparer.OrdinalIgnoreCase);

    private FrozenDictionary<string, string>? _frozenCategories;
    private FrozenDictionary<string, decimal>? _frozenPrices;
    private FrozenDictionary<string, string[]>? _frozenCategoryIndex;

    public void AddProduct(string code, string category, decimal price)
    {
        _categories[code] = category;
        _prices[code] = price;

        ref var list = ref CollectionsMarshal.GetValueRefOrAddDefault(_categoryIndex, category, out bool exists);
        if (!exists)
            list = new List<string>();
        list!.Add(code);

        // Invalidate frozen state on mutation
        _frozenCategories = null;
        _frozenPrices = null;
        _frozenCategoryIndex = null;
    }

    /// <summary>
    /// Freezes the catalog for maximum read throughput.
    /// </summary>
    public void Build()
    {
        _frozenCategories = _categories.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _frozenPrices = _prices.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _frozenCategoryIndex = _categoryIndex.ToFrozenDictionary(
            kvp => kvp.Key,
            kvp => kvp.Value.ToArray(),
            StringComparer.OrdinalIgnoreCase);
    }

    public string? GetCategory(string code)
    {
        var lookup = _frozenCategories ?? (IReadOnlyDictionary<string, string>)_categories;
        return lookup.TryGetValue(code, out var cat) ? cat : null;
    }

    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        var lookup = _frozenPrices ?? (IReadOnlyDictionary<string, decimal>)_prices;
        decimal total = 0m;
        foreach (var code in codes)
        {
            if (lookup.TryGetValue(code, out var price))
                total += price;
        }
        return total;
    }

    public List<string> GetProductsByCategory(string category)
    {
        // O(1) lookup via reverse index instead of O(n) full scan
        if (_frozenCategoryIndex is not null)
        {
            return _frozenCategoryIndex.TryGetValue(category, out var codes)
                ? new List<string>(codes)
                : new List<string>();
        }

        if (_categoryIndex.TryGetValue(category, out var list))
            return new List<string>(list);

        return new List<string>();
    }
}

